function feedCard(f){const keeperRecord=f.publisherRole==='keeper',title=keeperRecord?`${f.name} · 管家现场巡检`:`${f.name} · ${f.trade}`,plan=keeperRecord?`关联阶段：${f.stageName||f.trade} · 不替代师傅每日更新`:`本次施工内容：${f.remaining}`,expected=keeperRecord?(f.expected?`计划完成 ${date(f.expected)}`:'现场巡检补充记录'):`预计 ${date(f.expected)} 完成`;return `<article class="feed-card"><div class="feed-author"><span class="avatar">${esc(f.name[0])}</span><div><strong>${esc(title)}</strong><small>${date(f.date)} ${esc(f.time)} · ${esc(f.location)}</small></div></div><p>${esc(f.text)}</p>${f.sample?'<div class="evidence-placeholder">'+icon('camera')+'示例施工记录 · 尚未提供真实现场照片</div>':media(f.media)}<div class="feed-meta"><span>${esc(expected)}</span><span>同项目成员可见</span></div><p class="muted tiny">${esc(plan)}</p></article>`;}
