function stageChecklistView(s){const selected=new Set(s.submission?.checks||[]);return `<div class="stage-checklist">${s.checklist.map((item,index)=>`<div class="check-row ${selected.has(item.id)?'done':''}"><span>${selected.has(item.id)?'✓':index+1}</span><p>${esc(item.text)}</p></div>`).join('')}</div>`;}
function waterproofSummary(s){const w=s.submission?.waterproof;if(!w)return '';return `<div class="history-snapshot"><strong>两次闭水记录</strong><p>第一次：${esc(w.firstStart)} 至 ${esc(w.firstEnd)} · ${esc(w.firstHours)} 小时</p><p>${esc(w.firstWaterLevel)}</p><p>卫生间回填：已确认 · 第二遍防水：已确认</p><p>第二次：${esc(w.secondStart)} 至 ${esc(w.secondEnd)} · ${esc(w.secondHours)} 小时</p><p>${esc(w.secondWaterLevel)}</p></div>`;}
function waterproofNodesView(s){const records=s.waterproofNodes||[],byId=new Map(records.map(record=>[record.id,record])),next=WATERPROOF_NODE_TEMPLATES[records.length],canRecord=actor.role==='keeper'&&['active','planned','applied'].includes(s.status)&&next;return `${section('防水节点现场记录',`<span class="tag ${records.length===5?'green':'orange'}">${records.length}/5 已完成</span>`)}<div class="notice">5 个节点可以在不同日期分别记录。每个节点须由管家现场拍摄至少 3 张照片；视频只能补充。第 5 节点照片同时作为最终验收照片。</div>${WATERPROOF_NODE_TEMPLATES.map((node,index)=>{const record=byId.get(node.id),counts=onsiteEvidenceCounts(record?.media||[]);return `<div class="card" style="margin-top:10px"><div class="row"><h3>${index+1}. ${esc(node.name)}</h3>${record?tag('confirmed','已记录'):index===records.length?tag('active','下一节点'):tag('planned','待前序完成')}</div>${record?`<p>${esc(record.occurredAt)} · ${esc(record.by)}</p><p class="muted">${esc(record.note)}</p><p class="muted tiny">现场照片 ${counts.photos}/3${counts.videos?` · 补充视频 ${counts.videos} 段`:''}${record.revisions?.length?` · 已更正 ${record.revisions.length} 次`:''}</p>${media(record.media)}${actor.role==='keeper'&&['active','planned','applied'].includes(s.status)?btn('更正本节点','correct-waterproof-node',node.id,'text-button'):''}`:'<p class="muted">尚未记录</p>'}</div>`;}).join('')}${canRecord?`<div class="actions">${btn(`记录第 ${records.length+1} 个节点`,'waterproof-node',next.id)}</div>`:''}`;}
function stagePage(){
 const p=project(),s=p.stages.find(s=>s.id===detail);if(!s)return empty('未找到阶段');
 const open=unresolved(p,s.id),finalBlocks=s.kind==='final'?finalStageBlockers(p):[],blockers=[...(open.length?[`本阶段还有 ${open.length} 项问题未处理结束`]:[]),...finalBlocks],counts=onsiteEvidenceCounts(s.media),application=(s.applications||[]).at(-1),applicationCounts=onsiteEvidenceCounts(application?.media||[]),stageDescription=s.kind!=='final'&&!application&&!s.submission? '施工完成后由师傅申请、管家检查并提交、主业主最终确认。':s.description;
 const ownerActions=blockers.length?'<button class="primary" disabled aria-describedby="stage-blocker">确认阶段验收通过</button>'+btn('不通过','reject-stage',s.id,'secondary'):btn('确认阶段验收通过','accept-stage',s.id)+btn('不通过','reject-stage',s.id,'secondary');
 const workerCanApply=p.status!=='已完工'&&s.kind!=='final'&&['active','planned','returned'].includes(s.status)&&actor.role==='worker'&&member(p,actor).trade===s.trade;
 const waterproofNodesReady=s.kind!=='waterproof'||(s.waterproofNodes||[]).length===WATERPROOF_NODE_TEMPLATES.length;
 const keeperCanSubmit=p.status!=='已完工'&&actor.role==='keeper'&&(s.kind==='final'?['active','planned'].includes(s.status):s.status==='applied'&&waterproofNodesReady);
 const keeperCanReturn=p.status!=='已完工'&&s.kind!=='final'&&actor.role==='keeper'&&s.status==='applied';
 return `${tag(s.status)}<span class="muted tiny" style="margin-left:8px">第 ${s.order}/11 阶段 · ${esc(s.kind==='final'?'管家直接提交':s.trade+'申请 · 管家提交')}</span><h2 style="margin-top:12px">${esc(s.name)}</h2><p class="muted" style="margin-top:12px">${esc(stageDescription)}</p>
 ${p.status==='已完工'?'<div class="notice">项目已完工，本阶段记录已归档保留。如有新问题，请建立售后／保修记录。</div>':''}
 ${application?`<div class="notice ${application.outcome==='returned'?'orange':''}">师傅申请：${esc(application.by)} · ${esc(application.time)}<br>施工完成说明：${esc(application.note)}<br>现场影像：${applicationCounts.photos} 张照片${applicationCounts.videos?` · ${applicationCounts.videos} 段补充视频`:''}${application.outcome==='returned'?`<br>管家退回：${esc(application.resultNote||'需继续施工')}`:''}</div>${media(application.media)}`:''}
 ${s.submission?`<div class="notice">管家提交：${esc(s.submission.by)} · ${esc(s.submission.time)}<br>现场影像：${counts.photos} 张照片${counts.videos?` · ${counts.videos} 段补充视频`:''}</div>`:''}${media(s.media)}
 ${blockers.length&&s.status==='review'?`<div class="notice orange" id="stage-blocker" style="margin-top:16px">暂不能通过：${blockers.map(esc).join('；')}。</div>`:''}
 ${s.kind==='final'?`${section('竣工通过门槛')}<div class="gate-list">${p.finalTrial?.kind==='final-flow'?`<p class="green-text">✓ 本试用副本已模拟放行竣工流程；原项目仍需按实际完成前 10 个阶段、问题和材料确认。</p>${p.finalTrial.actualBlockers.map(x=>`<p>原项目当时未满足：${esc(x)}</p>`).join('')}`:finalBlocks.length?finalBlocks.map(x=>`<p>○ ${esc(x)}</p>`).join(''):'<p class="green-text">✓ 前 10 个阶段、问题和材料门槛均已满足</p>'}</div>`:''}
 ${s.kind==='waterproof'?waterproofNodesView(s):''}
 ${section('本阶段验收清单',`<span class="tag ${s.submission?'green':'gray'}">${s.submission?`${completedChecklistCount(s)}/${s.checklist.length} 已完成`:'管家提交时须逐项确认'}</span>`)}${stageChecklistView(s)}${waterproofSummary(s)}
 ${section('关联问题',`<span class="tag ${open.length?'orange':'green'}">${open.length?open.length+' 项未结束':'全部处理结束'}</span>`)}${p.issues.filter(i=>i.stage===s.id).map(issueCard).join('')||empty('暂无关联问题')}
 <div class="actions">${p.status==='已完工'?'':actor.role==='owner'&&s.status==='review'?ownerActions:workerCanApply?btn('施工完成，申请验收','request-stage',s.id):keeperCanSubmit?btn(s.kind==='final'?'提交竣工验收':'提交主业主验收','submit-stage',s.id)+(keeperCanReturn?btn('退回继续施工','return-stage-application',s.id,'secondary'):''):actor.role==='keeper'&&s.kind==='waterproof'&&s.status==='applied'&&!waterproofNodesReady?'<button class="primary" disabled>完成5个防水节点后提交</button>'+btn('退回继续施工','return-stage-application',s.id,'secondary'):actor.role==='keeper'&&s.status==='rejected'?btn('安排处理，师傅重新申请','followup-stage',s.id):''}</div>
 ${(s.snapshots||[]).map(snap=>{const issues=snap.issues||[];return `<div class="history-snapshot"><strong>${issues.length?'历史验收记录（旧规则）':'阶段验收确认记录'}</strong><p>${esc(snap.by)} · ${esc(snap.time)}</p>${issues.map(i=>`<p>• ${esc(i.title)}<br><span class="muted tiny">当时：${STATUS[i.status]?.[0]||i.status} · 当前：${STATUS[p.issues.find(x=>x.id===i.id)?.status]?.[0]||'查阅问题记录'}</span></p>`).join('')||'<p>验收时全部关联问题已处理结束。</p>'}${issues.length?'<p class="muted tiny">此处保留旧记录；当前阶段结果以上方状态为准。</p>':''}</div>`;}).join('')}
 ${section('阶段验收记录')}${history(s.history)}`;
}
function materialStateTag(m){return m.status==='pending'&&!materialEvidenceReady(m.media)?tag('pending','待现场补拍'):tag(m.status);}
function materialPage(){const m=project().materials.find(m=>m.id===detail);if(!m)return empty('未找到批次');const counts=onsiteEvidenceCounts(m.media),ready=materialEvidenceReady(m.media);const ownerActions=actor.role==='owner'&&m.status==='pending'?(ready?btn('确认本批材料','accept-material',m.id):'<button class="primary" disabled aria-describedby="material-evidence-blocker">确认本批材料</button>')+btn('材料有问题','reject-material',m.id,'secondary'):'';return `${materialStateTag(m)}<h2 style="margin-top:12px">${esc(m.name)}</h2>${details([['品牌',m.brand],['型号规格',m.spec],['本批数量',m.quantity+' '+m.unit],['到场日期',m.date],['使用位置',m.location],['登记人',project().keeper]])}${!ready&&m.status==='pending'?`<div class="notice orange" id="material-evidence-blocker">待现场补拍：当前 ${counts.photos}/3 张照片、${counts.videos}/1 段视频。补齐后主业主才能确认。</div>`:''}${media(m.media)}<div class="actions">${ownerActions}${actor.role==='keeper'&&m.status==='problem'?btn('提交处理结果','resubmit-material',m.id):''}${actor.role==='keeper'&&m.status==='pending'&&!ready?btn('补拍现场影像','supplement-material',m.id):''}${actor.role==='keeper'&&['problem','pending'].includes(m.status)?btn('更正批次资料','edit-material',m.id,'secondary'):''}</div><p class="muted tiny" style="margin-top:12px">本批材料确认与施工阶段验收分别进行。</p>${section('批次处理记录')}${history(m.history)}`;}
const extraEvidence=items=>{const photos=(items||[]).filter(x=>x.kind==='image'),files=(items||[]).filter(x=>['pdf','dwg','file'].includes(x.kind));return `${media(photos)}${files.map(f=>`<div class="file-card"><span class="file-type ${f.kind}">${f.kind==='file'?'资料':f.kind.toUpperCase()}</span><div><strong>${esc(f.name)}</strong><small>增项依据文件 · 记录名称永久保留</small></div></div>`).join('')}`;};
const extraCard=x=>{const p=project(),stage=p.stages.find(s=>s.id===x.stage)?.name||'未关联阶段';return go(`<div class="row">${tag(x.status)}<span class="muted tiny">V${x.version} · ${esc(x.location)}</span></div><h3>${esc(x.name)}</h3><p class="muted">${esc(stage)}${x.worker?' · '+esc(person(x.worker)):''}${x.start?' · '+date(x.start)+'—'+date(x.end):''}</p>${canSeeExtraPrice()?`<p><strong>${money(x.totalCost)}</strong> · 影响工期 ${esc(x.delayDays)} 天</p>`:'<p class="muted tiny">增项金额未对当前身份开放</p>'}`,'extra','card clickable',x.id);};
function extrasPage(){if(actor.role==='worker')return `<div class="notice">已安排给你的施工任务统一显示在施工安排中。</div>${go('查看施工安排','schedule','primary full')}`;const p=project(),list=p.extras||[];return `<div class="notice">增项须先由管家登记，主业主确认价格和工期影响后才能安排施工。每次改价或改内容都会建立新版本并重新确认。</div>${actor.role==='keeper'&&p.status!=='已完工'?btn(icon('plus')+' 登记增项','add-extra','','primary full'):''}${section('增项记录',`<span class="muted">共 ${list.length} 项</span>`)}${list.map(extraCard).join('')||empty('还没有增项记录')}`;}
function workerExtraTaskPage(x){const application=(x.applications||[]).at(-1),counts=onsiteEvidenceCounts(application?.media||[]),canApply=x.worker===actor.worker&&['extra_working','extra_returned'].includes(x.status);return `${tag(x.status)}<h2 style="margin-top:12px">${esc(x.name)}</h2>${details([['本次施工内容',x.content],['施工位置',x.location],['施工日期',x.start+' 至 '+x.end],['验收要求','施工完成后现场拍摄至少 3 张照片；视频只能补充']])}${application?`${section('我的验收申请')}<div class="notice ${application.outcome==='returned'?'orange':''}">${esc(application.time)}<br>${esc(application.note)}<br>现场照片 ${counts.photos}/3${counts.videos?` · 补充视频 ${counts.videos} 段`:''}${application.outcome==='returned'?`<br>需要继续完成：${esc(application.resultNote||'请按管家要求继续施工')}`:''}</div>${media(application.media)}`:''}<div class="actions">${canApply?btn('施工完成，申请验收','request-extra-acceptance',x.id):''}</div>`;}
function extraPage(){const p=project(),x=(p.extras||[]).find(x=>x.id===detail);if(!x)return empty(actor.role==='worker'?'未找到施工任务':'未找到增项记录');if(!extraVisibleToActor(x,actor))return empty(actor.role==='worker'?'这项施工任务尚未安排给当前师傅':'当前版本不可查看');if(actor.role==='worker')return workerExtraTaskPage(x);const stage=p.stages.find(s=>s.id===x.stage)?.name||'未关联阶段',application=(x.applications||[]).at(-1),appCounts=onsiteEvidenceCounts(application?.media||[]),submitCounts=onsiteEvidenceCounts(x.submission?.media||[]),price=canSeeExtraPrice()?details([['材料费',money(x.materialCost)],['人工费',money(x.laborCost)],['增项总价',money(x.totalCost)],['预计延期',x.delayDays+' 天']]):'<div class="notice">当前身份没有增项金额查看权限。</div>',versionList=(x.versions||[]).map(v=>`<div class="history-snapshot"><strong>V${v.version} · ${esc(v.name)}</strong><p>${esc(v.content)}</p>${canSeeExtraPrice()?`<p>${money(v.totalCost)} · 延期 ${esc(v.delayDays)} 天</p>`:''}<small>${esc(v.by)} · ${esc(v.time)}</small></div>`).reverse().join(''),ownerActions=actor.role==='owner'?(x.status==='extra_pending'?btn('确认价格与工期','accept-extra-proposal',x.id)+btn('拒绝本版','reject-extra-proposal',x.id,'secondary'):x.status==='extra_review'?btn('确认增项完成','accept-extra-completion',x.id)+btn('验收不通过','reject-extra-completion',x.id,'secondary'):x.status==='extra_cancel_pending'?btn('同意取消','accept-extra-cancel',x.id)+btn('不同意取消','reject-extra-cancel',x.id,'secondary'):x.status==='extra_settlement'?btn('确认终止结算','accept-extra-settlement',x.id)+btn('不同意结算','reject-extra-settlement',x.id,'secondary'):''):'',keeperActions=actor.role==='keeper'?(x.status==='extra_rejected'?btn('修改并重新提交','revise-extra',x.id)+btn('取消增项','cancel-extra-before',x.id,'secondary'):x.status==='extra_pending'?btn('撤回并取消','cancel-extra-before',x.id,'secondary'):x.status==='extra_confirmed'?btn('安排施工','schedule-extra',x.id)+btn('修改并重新确认','revise-extra',x.id,'secondary')+btn('申请取消','request-extra-cancel',x.id,'secondary'):x.status==='extra_applied'?btn('检查通过，提交业主','submit-extra',x.id)+btn('退回继续施工','return-extra',x.id,'secondary')+btn('申请终止结算','request-extra-settlement',x.id,'secondary'):x.status==='extra_followup'?btn('安排师傅继续施工','followup-extra',x.id)+btn('申请终止结算','request-extra-settlement',x.id,'secondary'):['extra_working','extra_returned','extra_review'].includes(x.status)?btn('申请终止结算','request-extra-settlement',x.id,'secondary'):''):'';return `${tag(x.status)}<span class="muted tiny" style="margin-left:8px">V${x.version}</span><h2 style="margin-top:12px">${esc(x.name)}</h2>${details([['施工位置',x.location],['所属阶段',stage],['原因／类别',x.reason],['施工内容',x.content],['责任师傅',person(x.worker)],['施工日期',x.start?x.start+' 至 '+x.end:'待管家安排']])}${price}${section('登记依据')}${extraEvidence(x.evidence)}${application?`${section('师傅申请验收')}<div class="notice">${esc(application.by)} · ${esc(application.time)}<br>${esc(application.note)}<br>现场照片 ${appCounts.photos}/3${appCounts.videos?` · 补充视频 ${appCounts.videos} 段`:''}</div>${media(application.media)}`:''}${x.submission?`${section('管家验收提交')}<div class="notice">${esc(x.submission.by)} · ${esc(x.submission.time)}<br>${esc(x.submission.note)}<br>新拍照片 ${submitCounts.photos}/3${submitCounts.videos?` · 补充视频 ${submitCounts.videos} 段`:''}</div>${media(x.submission.media)}`:''}${x.cancelRequest?`<div class="notice orange">取消原因：${esc(x.cancelRequest.note)}</div>`:''}${x.settlement?`${section('终止结算申请')}${details([['已完成工程量',x.settlement.completedQuantity],['实际费用',canSeeExtraPrice()?money(x.settlement.actualCost):'未授权查看'],['现场说明',x.settlement.note]])}${media(x.settlement.media)}`:''}<div class="actions">${ownerActions}${keeperActions}</div>${section('版本记录')}${versionList||empty('暂无版本记录')}${section('处理记录')}${history(x.history)}`;}
const warrantyCard=w=>go(`<div class="row">${tag(w.status)}<span class="muted tiny">${esc(w.location)}</span></div><h3>${esc(w.title)}</h3><p class="muted">${esc(w.description)}</p>`,'warrantyItem','card clickable',w.id);
function warrantyPage(){const p=project();return `<div class="notice">售后／保修问题单独记录，不改变已经通过的竣工验收结论。</div><div class="row" style="margin-bottom:16px"><span class="muted">共 ${p.afterSales.length} 条记录</span>${p.status==='已完工'&&['owner','family'].includes(actor.role)?btn('新建售后问题','report-warranty','','secondary'):''}</div>${p.afterSales.map(warrantyCard).join('')||empty(p.status==='已完工'?'还没有售后／保修问题记录':'项目完工后可在这里建立售后／保修问题记录')}`;}
function warrantyItemPage(){const w=project().afterSales.find(w=>w.id===detail);if(!w)return empty('未找到售后记录');return `${tag(w.status)}<h2 style="margin-top:12px">${esc(w.title)}</h2>${details([['位置',w.location],['归档关系','独立售后记录，不改变竣工结论']])}<p>${esc(w.description)}</p>${media(w.media)}<div class="actions">${actor.role==='keeper'&&['checking','working'].includes(w.status)?btn('记录处理进展','followup-warranty',w.id):actor.role==='owner'&&w.status==='working'?btn('确认处理完成','close-warranty',w.id):''}</div>${section('处理记录')}${history(w.history)}<form class="comment-form" id="warranty-comment-form"><input aria-label="留言内容" name="note" required maxlength="500" placeholder="补充售后处理信息…"><button class="secondary" type="submit">发送</button></form>`;}
function designPage(){const p=project(),list=p.designs.filter(d=>d.kind===designTab&&(showHistory||d.current));return `<div class="tabs">${[['effect','效果图'],['drawing','施工图'],['panorama','720°全景']].map(([id,n])=>`<button class="${designTab===id?'active':''}" data-design-tab="${id}">${n}</button>`).join('')}</div><div class="row" style="margin-bottom:16px"><span class="muted">${designTab==='effect'?'按空间查看家的样子':designTab==='drawing'?'PDF 可查看 · DWG 可保存':'从全景中提前逛一逛新家'}</span>${['director','designer'].includes(actor.role)?btn('添加资料','add-design','','text-button'):''}</div>${designTab==='drawing'?`<label class="checkbox tiny"><input type="checkbox" id="show-history" ${showHistory?'checked':''}>显示历史版本</label>`:''}${list.map(d=>`<article class="card"><div class="row"><span class="tag ${d.current?'':'gray'}">${d.current?'当前资料':'历史资料'} · ${esc(d.version)}</span><span class="muted tiny">${esc(d.room)}</span></div><h3>${esc(d.name)}</h3>${d.kind==='effect'?d.files.map(f=>{const url=f.url||localFiles.get(f.key)?.url;return url?`<a href="${esc(url)}" target="_blank" rel="noopener"><img class="poster" src="${esc(url)}" alt="${esc(d.name)}"></a>`:`<div class="evidence-placeholder">${esc(f.name)} · 刷新后需重新选择文件</div>`;}).join(''):d.kind==='drawing'?d.files.map((f,index)=>`<div class="file-card"><span class="file-type ${f.kind}">${f.kind.toUpperCase()}</span><div style="min-width:0"><strong>${esc(f.name)}</strong><small>${f.sample?'示例文件卡 · 尚未提供实际文件':'本机选择的文件 · 当前版本'}</small>${btn(f.kind==='dwg'?'获取源文件':'打开 PDF','open-file',d.id+'|'+index,'text-button')}</div></div>`).join(''):`<div class="hero" style="height:170px;margin:14px 0"><img src="./assets/design-poster.png" alt="全景样例封面"><div class="hero-content"><h2>720° 看见整个家</h2><p>旋转视角 · 切换房间</p></div></div><a class="primary full" target="_blank" rel="noopener noreferrer" href="${esc(d.url)}">打开全景 ↗</a><p class="muted tiny">在新页面打开原作品。样例由你人工验证可转动和切换房间；小程序内接入仍待验证。</p>`}<p class="muted tiny" style="margin-top:12px">更新于 ${d.date}${d.kind==='drawing'?' · PDF 或 DWG 至少一种':''}</p></article>`).join('')||empty('暂无这一类资料')}${designTab==='effect'?'<p class="muted tiny" style="margin-top:14px">海报为用户提供的“盛世港府”样例，不作为演示施工项目的真实资料。</p>':''}`;}
function peoplePage(){const p=project();return `<div class="row" style="margin-bottom:14px"><p class="muted">${p.members.length} 位成员 · 各工种共同协作</p>${actor.role==='keeper'?btn('邀请成员','invite','','secondary'):''}</div>${p.members.map(m=>{const access=(actor.role==='owner'&&m.role==='family')||(actor.role==='director'&&m.role==='designer')?btn(m.extraPriceAuthorized?'取消增项金额权限':'授权查看增项金额','extra-price-access',m.id,'text-button'):'';return `<div class="person-row"><span class="avatar">${esc(m.name[0])}</span><div><strong>${esc(m.name)}</strong><small>${esc(m.trade||ROLES.find(r=>r[0]===m.role)?.[2]||'项目成员')}${m.extraPriceAuthorized?' · 可看增项金额':''}</small></div><div>${tag('active',ROLES.find(r=>r[0]===m.role)?.[1]||m.role)}${access}</div></div>`;}).join('')}${actor.role==='keeper'?`${section('待核对的加入申请')}<div class="notice">核对姓名、身份和负责工种后再通过。申请通过前不能查看项目资料。</div>${p.applications.filter(a=>a.status==='pending').map(a=>`<div class="card"><h3>${esc(a.name)}</h3><p class="muted">${ROLES.find(r=>r[0]===a.role)?.[1]} ${esc(a.trade)}</p><div class="actions">${btn('身份核对无误，加入','approve-member',a.id)}${btn('不通过','reject-member',a.id,'secondary')}</div></div>`).join('')||empty('没有待核对的申请')}${p.applications.some(a=>a.status!=='pending')?`<details style="margin-top:15px"><summary class="muted">已处理的申请</summary>${p.applications.filter(a=>a.status!=='pending').map(a=>`<p class="muted" style="margin-top:10px">${esc(a.name)} · ${a.status==='approved'?'已加入':'未通过：'+esc(a.note)}</p>`).join('')}</details>`:''}`:''}`;}
const pages={home:homePage,projects:()=>`${actor.role==='director'?btn(icon('plus')+' 创建装修项目','create-project','','primary full'):''}<div class="stack" style="margin-top:18px">${visibleProjects(state,actor).map(p=>`<button class="card clickable" data-project="${p.id}"><div class="row">${tag('active',p.status)}<span class="muted">${esc(p.area)}</span></div><h3>${esc(p.name)}</h3><p class="muted">管家：${esc(p.keeper)} · ${p.members.length} 位成员</p></button>`).join('')}</div>`,
feed:()=>`<div class="row" style="margin-bottom:18px">${go('施工安排 →','schedule')}${actor.role==='worker'?btn(icon('camera')+' 发布记录','daily'):actor.role==='keeper'?`${btn(icon('camera')+' 发布现场巡检','keeper-daily')}${btn('反馈问题','report-issue','','secondary')}`:btn('反馈问题','report-issue','','secondary')}</div>${tabs(['全部',...new Set(project().members.filter(m=>m.trade).map(m=>m.trade))])}<p class="muted tiny">演示日期：2026年9月15日 · 发布后立即可见；管家巡检不计入师傅每日更新。</p>${project().feed.filter(f=>filter==='全部'||f.trade===filter).map(feedCard).join('')||empty('这个工种还没有发布记录')}`,
schedule:schedulePage,todos:()=>{const p=project(),entries=[['issues','问题整改',p.issues.filter(i=>!['closed','acknowledged'].includes(i.status)).length,'issue'],['stages','阶段验收',p.stages.filter(s=>s.status==='review').length,'todo'],['materials','材料确认',p.materials.filter(m=>m.status==='pending').length,'material']];if(actor.role!=='worker')entries.push(['extras','增项确认',(p.extras||[]).filter(x=>!['extra_completed','extra_cancelled','extra_terminated'].includes(x.status)).length,'extra']);if(p.status==='已完工'||p.afterSales.length)entries.push(['warranty','售后／保修',p.afterSales.filter(w=>w.status!=='closed').length,'issue']);return `${['family','designer'].includes(actor.role)?'<div class="notice">这里可以查看项目处理进度；正式确认由主业主操作。</div>':''}<div class="stack">${entries.map(([r,n,c,i])=>go(`<span>${icon(i)} ${n}</span><span>${c} 项 <b>›</b></span>`,r,'list-button')).join('')}</div>${section(actor.role==='worker'?'我负责的整改':actor.role==='keeper'?'待检查问题':actor.role==='designer'?'最近项目动态':'最近的待确认事项')}${(actor.role==='worker'?p.issues.filter(i=>i.worker===actor.worker&&i.status==='working'):actor.role==='keeper'?p.issues.filter(i=>i.status==='checking'):p.issues.filter(i=>['review','explanation'].includes(i.status))).map(issueCard).join('')||empty('目前没有这一类待办')}${go(p.status==='已完工'?'查看售后／保修记录 →':'查看施工安排 →',p.status==='已完工'?'warranty':'schedule','secondary full')}`;},
issues:()=>`<div class="row" style="margin-bottom:16px"><p class="muted">发现 → 检查 → 整改 → 业主验收</p>${project().status==='已完工'?go('售后／保修记录 →','warranty','secondary'):btn('提出问题','report-issue','','secondary')}</div>${tabs(['全部','待处理','已结束'])}${project().issues.filter(i=>filter==='全部'||(filter==='待处理'&&!['closed','acknowledged'].includes(i.status))||(filter==='已结束'&&['closed','acknowledged'].includes(i.status))).map(issueCard).join('')||empty('暂无问题记录')}`,issue:issuePage,
stages:()=>`<div class="notice">前 10 个阶段由师傅施工完成后拍摄至少 3 张照片申请验收，管家检查后提交，主业主最终确认。防水阶段由管家分 5 个节点分别拍照；其他普通阶段由管家另拍至少 3 张照片。竣工阶段由管家直接提交。</div>${catalogUpdate.changed||finalChecklistUpdate.changed?'<div class="notice">已为浏览器中保存的项目更新最新阶段清单；原问题、材料和验收历史均已保留。</div>':''}${policyUpdate.restoredStages?'<div class="notice orange">已按新规则检查旧演示记录，将带问题通过的阶段恢复为待验收；原记录保留在阶段详情中。</div>':''}${project().stages.filter(s=>s.order<=11).map(s=>{const counts=onsiteEvidenceCounts(s.media),application=(s.applications||[]).at(-1),applicationCounts=onsiteEvidenceCounts(application?.media||[]),managerEvidence=s.kind==='waterproof'?`防水节点 ${(s.waterproofNodes||[]).length}/5`:`管家验收照片 ${counts.photos}/3`;return go(`<div class="row">${tag(s.status)}<span class="muted">第 ${s.order}/11 · ${esc(s.kind==='final'?'管家直接提交':s.trade+'申请 · 管家提交')}</span></div><h3>${esc(s.name)}</h3><p class="muted">${s.kind==='final'?`清单 ${s.submission?completedChecklistCount(s):0}/${s.checklist.length} · 管家照片 ${counts.photos}/3`:`师傅申请照片 ${applicationCounts.photos}/3 · ${managerEvidence} · 清单 ${s.submission?completedChecklistCount(s):0}/${s.checklist.length}`}${unresolved(project(),s.id).length?' · '+unresolved(project(),s.id).length+' 项问题未结束':''}</p>`,'stage','card clickable',s.id);}).join('')||empty('暂无阶段资料')}`,stage:stagePage,
materials:()=>`<div class="notice">每次到场单独记录，补送也作为新批次。每批须现场拍摄至少 3 张照片且录制 1 段视频，补齐后由主业主逐批确认。</div>${actor.role==='keeper'&&project().status!=='已完工'?btn(icon('plus')+' 登记新批次','add-material','','primary full'):''}${section('进场批次',`<span class="muted">共 ${project().materials.length} 批</span>`)}${project().materials.map((m,index)=>{const counts=onsiteEvidenceCounts(m.media);return go(`<div class="row">${materialStateTag(m)}<span class="muted tiny">第 ${index+1} 批 · ${date(m.date)}</span></div><h3>${esc(m.name)}</h3><p class="muted">${esc(m.spec)} · ${esc(m.quantity)} ${esc(m.unit)}</p>${!materialEvidenceReady(m.media)?`<p class="muted tiny">现场影像：${counts.photos}/3 张照片 · ${counts.videos}/1 段视频</p>`:''}`,'material','card clickable',m.id);}).join('')||empty('还没有材料进场记录')}`,material:materialPage,extras:extrasPage,extra:extraPage,warranty:warrantyPage,warrantyItem:warrantyItemPage,design:designPage,people:peoplePage};
const field=(name,label,value='',type='text',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra} required></label>`;
const textarea=(name,label,value='')=>`<label class="field">${label}<textarea name="${name}" maxlength="1500" required>${esc(value)}</textarea></label>`;
const select=(name,label,options,value='')=>`<label class="field">${label}<select name="${name}" required>${options.map(([id,n])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(n)}</option>`).join('')}</select></label>`;
const LOCATION_OPTIONS=['全屋','厨房','餐厅','前阳台','后阳台','洗衣房','主卧','次卧1','次卧2','儿童房','书房','客卫','主卫'];
const locationParts=value=>String(value||'').split(/[、,，/]+/).map(v=>v.trim()).filter(Boolean);
const locationField=(value='',label='施工位置',fieldName='location')=>{const selected=new Set(locationParts(value));return `<fieldset class="location-field"><legend>${esc(label)}</legend><div class="location-options" aria-label="常用${esc(label)}">${LOCATION_OPTIONS.map(name=>`<button type="button" class="location-option ${selected.has(name)?'active':''}" data-location-option="${esc(name)}" aria-pressed="${selected.has(name)}">${esc(name)}</button>`).join('')}</div><label class="field"><span>${esc(label)}（可自由填写）</span><input name="${esc(fieldName)}" type="text" value="${esc(value)}" placeholder="可选择上方位置，也可在这里输入其他位置" required></label></fieldset>`;};
function syncLocationOptions(input){const selected=new Set(locationParts(input.value)),box=input.closest('.location-field');box?.querySelectorAll('[data-location-option]').forEach(button=>{const active=selected.has(button.dataset.locationOption);button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});}
function toggleLocationOption(button){const input=button.closest('.location-field')?.querySelector('input[type=text]');if(!input)return;const values=locationParts(input.value),name=button.dataset.locationOption,index=values.indexOf(name);if(index>=0)values.splice(index,1);else values.push(name);input.value=values.join('、');syncLocationOptions(input);input.focus();}
const fileField=(name='files',label='选择文件',accept='image/*',required=false)=>`<label class="field">${label}<input type="file" name="${name}" accept="${accept}" multiple ${required?'required':''}><small>设计资料仍使用本机文件。刷新后保留名称，重新预览需再次选择文件；演示单次最多 30MB。</small></label><div class="media-grid" id="preview-${name}"></div>`;
const captureField=(prefix,label,requirement)=>`<fieldset class="media-field"><legend>${label}</legend><div class="capture-actions"><label class="capture-button">${icon('camera')} 拍摄照片<input class="file-trigger" type="file" name="${prefix}-photos" accept="image/*" capture="environment" multiple data-media-group="media" data-source="capture"></label><label class="capture-button">${icon('camera')} 录制视频<input class="file-trigger" type="file" name="${prefix}-video" accept="video/*" capture="environment" data-media-group="media" data-source="capture"></label></div><small>${requirement} 电脑原型会用文件选择模拟相机；正式小程序只调用相机。</small><div class="media-grid" id="preview-${prefix}-photos"></div><div class="media-grid" id="preview-${prefix}-video"></div></fieldset>`;
const uploadField=prefix=>`<fieldset class="media-field"><legend>从手机相册或文件补充</legend><div class="capture-actions"><label class="upload-button">上传照片<input class="file-trigger" type="file" name="${prefix}-upload-photos" accept="image/*" multiple data-media-group="media" data-source="upload"></label><label class="upload-button">上传视频<input class="file-trigger" type="file" name="${prefix}-upload-videos" accept="video/*" multiple data-media-group="media" data-source="upload"></label></div><small>上传照片会写入上传时间水印。此入口只用于提出问题和问题整改。</small><div class="media-grid" id="preview-${prefix}-upload-photos"></div><div class="media-grid" id="preview-${prefix}-upload-videos"></div></fieldset>`;
const issueMediaField=(prefix,requiredText)=>`${captureField(prefix,'现场拍摄',requiredText)}${uploadField(prefix)}`;
const checklistForm=s=>`<fieldset class="checklist-field"><legend>逐项确认验收清单（${s.checklist.length} 项）</legend>${s.checklist.map((item,index)=>`<label class="check-item"><input type="checkbox" name="check-${item.id}" value="${item.id}" required><span><b>${index+1}</b>${esc(item.text)}</span></label>`).join('')}</fieldset>`;
const waterproofNodeForm=(node,record=null,correcting=false)=>`<div class="notice">这是第 ${WATERPROOF_NODE_TEMPLATES.findIndex(item=>item.id===node.id)+1}/5 个防水节点。请在现场单独记录，不能从相册上传。</div>${field('occurredAt',node.timeLabel,record?.occurredAt||node.defaultTime,'datetime-local')}${textarea('note',node.noteLabel,record?.note||node.defaultNote)}${correcting?textarea('reason','更正原因'):''}${captureField('waterproof-node',node.name+'现场影像','必须由管家现场拍摄至少 3 张照片；视频只能补充，不能替代照片。照片自动写入拍摄时间水印。')}`;
function modal(title,content,onSubmit,label='确认提交'){$('#dialog-content').innerHTML=`<div class="dialog-head"><h3>${title}</h3><button data-action="close-dialog" aria-label="关闭">×</button></div><div class="dialog-body">${onSubmit?'<form id="action-form" class="form-grid">':''}${content}${onSubmit?`<div class="form-error" id="form-error" role="alert"></div><div class="actions"><button class="secondary" type="button" data-action="close-dialog">取消</button><button class="primary" type="submit">${label}</button></div></form>`:''}</div>`;$('#dialog').showModal();if(onSubmit)$('#action-form').onsubmit=async e=>{e.preventDefault();const submit=e.submitter;submit.disabled=true;try{const fd=new FormData(e.target),data=Object.fromEntries([...fd.entries()].filter(([,v])=>typeof v==='string'));for(const input of e.target.querySelectorAll('input[type=file]')){const selected=await collectFiles(input),group=input.dataset.mediaGroup;if(group)data[group]=[...(data[group]||[]),...selected];else data[input.name]=selected;}await onSubmit(data);}catch(error){$('#form-error').textContent=error.message;}finally{submit.disabled=false;}};}
const mediaTimestamp=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')} ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;
async function watermarkPhoto(file,source,timestamp){let image,cleanup=()=>{};try{if(globalThis.createImageBitmap)image=await createImageBitmap(file,{imageOrientation:'from-image'});else{const url=URL.createObjectURL(file);cleanup=()=>URL.revokeObjectURL(url);image=new Image();image.src=url;await image.decode();}const width=image.width||image.naturalWidth,height=image.height||image.naturalHeight,scale=Math.min(1,1920/Math.max(width,height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(width*scale));canvas.height=Math.max(1,Math.round(height*scale));const ctx=canvas.getContext('2d');ctx.drawImage(image,0,0,canvas.width,canvas.height);const fontSize=Math.max(20,Math.round(canvas.width*.025)),pad=Math.max(12,Math.round(fontSize*.65)),text=`${source==='capture'?'现场拍摄':'上传时间'} ${timestamp}`;ctx.font=`600 ${fontSize}px system-ui, sans-serif`;const barHeight=fontSize+pad*2;ctx.fillStyle='rgba(10,22,38,.62)';ctx.fillRect(0,canvas.height-barHeight,canvas.width,barHeight);ctx.fillStyle='#fff';ctx.textBaseline='middle';ctx.fillText(text,pad,canvas.height-barHeight/2);const blob=await new Promise((resolve,reject)=>canvas.toBlob(x=>x?resolve(x):reject(Error('照片水印生成失败')),'image/jpeg',.9));return new File([blob],file.name.replace(/\.[^.]+$/, '')+'_时间水印.jpg',{type:'image/jpeg'});}finally{image?.close?.();cleanup();}}
async function collectFiles(input){const files=[...input.files];if(files.reduce((n,f)=>n+f.size,0)>30*1024*1024)throw Error('演示单次请选择合计不超过 30MB 的文件');return Promise.all(files.map(async f=>{const ext=f.name.split('.').pop().toLowerCase(),kind=f.type.startsWith('video/')?'video':f.type.startsWith('image/')?'image':['pdf','dwg'].includes(ext)?ext:['doc','docx','xls','xlsx','txt'].includes(ext)?'file':'unsupported',source=input.dataset.source||'file';if(kind==='unsupported'||(input.dataset.mediaGroup&&!['image','video'].includes(kind))||(input.accept==='image/*'&&kind!=='image')||(input.accept==='video/*'&&kind!=='video')||(input.accept==='.pdf,.dwg'&&!['pdf','dwg'].includes(kind)))throw Error('文件格式与资料类型不符');let found=[...localFiles.entries()].find(([,v])=>v.file===f&&v.source===source);if(found)return found[1].meta;const timestamp=source==='file'?'':mediaTimestamp(new Date()),previewFile=kind==='image'&&source!=='file'?await watermarkPhoto(f,source,timestamp):f,key='file-'+crypto.randomUUID(),meta={key,name:f.name,kind,...(source==='file'?{}:{source,timestamp})},entry={url:URL.createObjectURL(previewFile),file:f,source,meta};localFiles.set(key,entry);return meta;}));}
function materialForm(m){const existing=!!m;m=m||{date:TODAY,unit:'米'};return `${field('name','材料名称',m.name)}${field('brand','品牌',m.brand)}${field('spec','型号规格',m.spec)}<div class="form-pair">${field('quantity','本批数量',m.quantity,'number','min="0.01" step="any"')}${field('unit','单位',m.unit)}</div>${field('date','进场日期',m.date,'date')}${locationField(m.location,'使用位置')}${existing?textarea('note','更正原因'):captureField('material-new','材料进场现场影像','必须拍摄至少 3 张现场照片，并录制 1 段现场视频。照片自动写入拍摄时间水印。')}`;}
const extraBasisField=prefix=>`<fieldset class="media-field"><legend>增项依据（至少一种）</legend><div class="capture-actions"><label class="capture-button">${icon('camera')} 拍摄现场照片<input class="file-trigger" type="file" name="${prefix}-photos" accept="image/*" capture="environment" multiple data-media-group="media" data-source="capture"></label><label class="upload-button">选择报价单／图纸／说明文件<input class="file-trigger" type="file" name="files" accept="image/*,.pdf,.dwg,.doc,.docx,.xls,.xlsx,.txt" multiple></label></div><small>可提供现场照片，或选择报价单、相关图纸、说明文件；至少提供一种依据。</small><div class="media-grid" id="preview-${prefix}-photos"></div><div class="media-grid" id="preview-files"></div></fieldset>`;
function extraForm(x){const p=project(),existing=!!x;x=x||{materialCost:0,laborCost:0,delayDays:0};return `${field('name','增项名称',x.name)}${locationField(x.location||'','施工位置')}${select('stage','所属施工阶段',p.stages.map(s=>[s.id,s.name]),x.stage)}${select('reason','增项原因／类别',[['业主新增需求','业主新增需求'],['设计变更','设计变更'],['现场条件变化','现场条件变化'],['原合同漏项','原合同漏项'],['其他','其他']],x.reason)}${textarea('content','增项施工内容',x.content)}<div class="form-pair">${field('materialCost','材料费（元）',x.materialCost,'number','min="0" step="0.01"')}${field('laborCost','人工费（元）',x.laborCost,'number','min="0" step="0.01"')}</div>${field('delayDays','预计影响工期（天）',x.delayDays,'number','min="0" step="1"')}<div class="notice">增项总价自动按“材料费＋人工费”计算。修改已确认的内容、价格或延期天数时，会建立新版本并重新由主业主确认。</div>${extraBasisField(existing?'extra-revision':'extra-new')}`;}
function scheduleForm(id='',availabilityId=''){const p=project(),a=p.availability.find(a=>a.id===availabilityId),s=p.schedules.find(s=>s.id===id)||{start:TODAY,end:'2026-09-20',excluded:[],trade:a?.trade||p.members.find(m=>m.trade)?.trade,worker:a?.worker};modal('安排施工日期',`${a?`<div class="notice">${person(a.worker)}反馈最早 ${date(a.date)} 可进场。请结合现场确认实际日期。</div>`:''}${select('trade','施工工种',[...new Set(p.members.filter(m=>m.trade).map(m=>m.trade))].map(t=>[t,t]),s.trade)}${select('worker','主要上传责任人',p.members.filter(m=>m.role==='worker').map(m=>[m.id,m.name+' · '+m.trade]),s.worker)}<div class="form-pair">${field('start','开始日期',a?.date||s.start,'date')}${field('end','结束日期',s.end,'date')}</div><label class="field">休息 / 停工日期（选填）<input name="excluded" value="${esc(s.excluded.join(', '))}" placeholder="如 2026-09-16，多个日期用逗号分隔"></label>${textarea('remaining','本次施工内容',s.remaining||'')}`,d=>run('saveSchedule',{...d,id,availabilityId},'施工安排已更新'),'保存施工安排');}
function designFields(kind){return kind==='panorama'?field('url','全景分享链接','','url','placeholder="https://…"'):fileField('files',kind==='drawing'?'施工图文件（PDF 或 DWG，至少一种）':'效果图图片',kind==='drawing'?'.pdf,.dwg':'image/*',true);}
function designForm(){modal('添加设计资料',`${select('kind','资料类型',[['effect','普通效果图'],['drawing','施工图 PDF／DWG'],['panorama','720°全景链接']],designTab)}${field('name','资料名称')}${field('version','版本','','text','placeholder="如 V3；同名资料将保留旧版本"')}${locationField('','对应空间','room')}<div id="design-file-fields">${designFields(designTab)}</div>`,d=>run('addDesign',d,'设计资料已添加，同项目成员可查看'),'保存资料');$('#action-form select[name=kind]').onchange=e=>{$('#design-file-fields').innerHTML=designFields(e.target.value);};}
function handle(action,id){const p=project(),noteFlow=(title,label,command,message)=>modal(title,textarea('note',label),d=>run(command,{...d,id},message));switch(action){
case 'close-dialog':$('#dialog').close();break;
case 'reset':modal(finalTrialMode?'重新开始竣工试用':'恢复初始演示',finalTrialMode?'<p>只重置竣工试用副本，再次从原项目复制当前资料；原项目不会改变。</p>':'<p>清空在本原型中新增的记录、文件预览与状态变化，恢复最初的示例场景。</p>',()=>{try{if(finalTrialMode){const original=JSON.parse(localStorage.getItem(MAIN_KEY));state=createFinalTrialState(original?.version===1&&Array.isArray(original.projects)?original:seed());localStorage.setItem(KEY,JSON.stringify(state));}else{state=seed();localStorage.removeItem(KEY);}}catch(error){storageWarning=error.message||'未能保存试用副本';$('#dialog').close();render();return;}localFiles.forEach(f=>URL.revokeObjectURL(f.url));localFiles.clear();actor={role:'owner',worker:'w1'};projectId='p1';route='home';detail='';$('#dialog').close();location.hash='home';render();notify(finalTrialMode?'竣工试用副本已重新开始':'已恢复初始演示数据');},finalTrialMode?'重新开始':'恢复演示');break;
case 'create-project':modal('创建装修项目',`${field('name','项目名称','','text','placeholder="如 小区 · 楼栋房号"')}${select('keeper','指定管家',[['陈管家','陈管家'],['何管家','何管家']])}<div class="form-pair">${field('area','建筑面积','','text','placeholder="如 128㎡"')}${field('layout','户型','','text','placeholder="如 三室两厅"')}</div>${field('start','计划开工日',TODAY,'date')}`,d=>run('createProject',d,'项目已创建，管家已指定'),'创建项目');break;
case 'daily':{const s=p.schedules.find(s=>s.trade===member(p,actor).trade);modal('发布今天的现场记录',`<div class="notice">${esc(p.name)}<br>${esc(member(p,actor).trade)} · ${TODAY} · 发布后同项目成员立即可见</div>${locationField()}${textarea('text','今天完成了什么？')}${captureField('daily','现场记录','完成一种即可：拍摄至少 3 张现场照片，或录制至少 1 段现场视频。照片自动写入拍摄时间水印。')}<div class="notice read-only-plan"><strong>当前施工安排（只读）</strong><br>本次施工内容：${esc(s?.remaining||'待管家补充')}<br>计划完成日期：${esc(s?.end||'待管家安排')}<br><span class="tiny">如需调整，请联系管家在“施工安排”中修改。</span></div>`,d=>run('publishDaily',d,'现场记录已发布，同项目成员现在可见'),'发布记录');break;}
case 'keeper-daily':modal('发布现场巡检进度',`<div class="notice">管家巡检记录发布后立即对项目成员可见，但不会替代师傅当天应发布的施工记录。</div>${select('stage','关联施工阶段',p.stages.filter(s=>s.kind!=='final').map(s=>[s.id,`${s.name} · ${s.trade}`]))}${locationField()}${textarea('text','现场进度与巡检情况')}${captureField('keeper-daily','现场巡检影像','完成一种即可：拍摄至少 3 张现场照片，或录制至少 1 段现场视频。照片自动写入拍摄时间水印。')}`,d=>run('publishKeeperProgress',d,'现场巡检已发布，同项目成员现在可见；师傅每日更新任务保持不变'),'发布现场巡检');break;
case 'report-issue':modal('提出现场问题',`${field('title','问题标题')}${field('location','问题位置')}${select('stage','关联施工阶段',[['','暂不关联'],...p.stages.map(s=>[s.id,s.name])])}${textarea('description','具体情况')}${issueMediaField('issue-report','照片或视频可选；可以现场拍摄，也可以从手机相册或文件补充。')}`,d=>run('reportIssue',d,'问题已交管家检查'),'提交给管家');$('#action-form select[name=stage]').required=false;break;
case 'assign-issue':{const i=p.issues.find(i=>i.id===id);modal('安排师傅整改',`${select('worker','责任师傅',p.members.filter(m=>m.role==='worker').map(m=>[m.id,m.name+' · '+m.trade]),i.worker)}${field('deadline','约定完成日期',i.deadline||'2026-09-17','date')}${textarea('note','检查结果与整改要求')}`,d=>run('assignIssue',{...d,id},'整改任务已安排给师傅'),'安排整改');break;}
case 'explain-issue':modal('提交无需整改说明',`<div class="notice">提交后由主业主决定是否认可；业主认可前保持待确认。</div>${textarea('note','检查说明与依据')}`,d=>run('explainIssue',{...d,id},'说明已提交，等待主业主认可'),'提交主业主确认');break;
case 'rectify':modal('提交整改结果',`${textarea('note','本次如何整改？')}${issueMediaField('rectification','至少提供 1 张照片或 1 段视频；可以现场拍摄，也可以从手机相册或文件补充。')}<div class="notice">提交后进入主业主验收，原问题和历次记录保留。</div>`,d=>run('submitRectification',{...d,id},'整改已提交，等待主业主验收'),'申请业主验收');break;
case 'accept-issue':{const i=p.issues.find(i=>i.id===id),ex=i.status==='explanation';modal(ex?'认可无需整改说明':'确认整改验收通过',`<p>${esc(i.title)}</p><p class="muted">${ex?'认可后结束反馈，检查说明保留。':'确认后标记问题已解决，处理记录保留。'}</p>`,()=>run('acceptIssue',{id},ex?'已认可说明':'整改验收已通过'),ex?'认可说明':'确认验收通过');break;}
case 'reject-issue':noteFlow('填写意见，继续处理','不通过 / 仍有异议的原因','rejectIssue','意见已交管家继续跟进');break;
case 'accept-stage':{const s=p.stages.find(s=>s.id===id),open=unresolved(p,id),blocks=s.kind==='final'?finalStageBlockers(p):[];if(open.length||blocks.length)throw Error([open.length?`还有 ${open.length} 项问题未处理结束`:null,...blocks].filter(Boolean).join('；'));modal(s.kind==='final'?'确认竣工验收与交付':'确认阶段验收',`<h3>${esc(s.name)}</h3><p>${s.kind==='final'?'确认后项目状态变为“已完工”，施工、问题、材料和验收历史归档保留；后续问题另建售后／保修记录。':'本阶段关联问题已全部处理结束，请确认阶段施工及验收资料符合要求。'}</p>`,()=>run('acceptStage',{id},s.kind==='final'?'项目已完工并归档':'主业主已确认阶段验收通过'),s.kind==='final'?'确认竣工并交付':'确认阶段通过');break;}
case 'reject-stage':noteFlow('阶段验收不通过','需要继续处理的内容','rejectStage','已交管家跟进阶段问题');break;
case 'followup-stage':noteFlow('跟进阶段问题','检查结果与师傅处理安排','followupStage','已记录管家安排，师傅完善后可重新提交');break;
case 'request-stage':modal('施工完成，申请验收',`${textarea('note','施工完成说明')}${captureField('stage-application','师傅申请验收现场影像','必须现场拍摄至少 3 张照片；视频可以补充，但不能代替这 3 张照片。照片自动写入拍摄时间水印。')}<div class="notice">申请后由管家到场检查。管家检查通过后，还需另拍至少 3 张现场照片并提交主业主验收。</div>`,d=>run('requestStageAcceptance',{...d,id},'已申请管家验收'),'申请管家验收');break;
case 'return-stage-application':noteFlow('退回继续施工','检查不通过原因和需要继续完成的内容','returnStageApplication','已退回师傅继续施工');break;
case 'waterproof-node':{const s=p.stages.find(s=>s.id===detail),node=WATERPROOF_NODE_TEMPLATES.find(node=>node.id===id);if(!s||!node)throw Error('未找到防水节点');modal(`记录节点：${node.name}`,waterproofNodeForm(node),d=>run('submitWaterproofNode',{...d,id:s.id,nodeId:node.id},`第 ${(s.waterproofNodes||[]).length+1} 个防水节点已记录`),'保存本节点');break;}
case 'correct-waterproof-node':{const s=p.stages.find(s=>s.id===detail),node=WATERPROOF_NODE_TEMPLATES.find(node=>node.id===id),record=(s?.waterproofNodes||[]).find(record=>record.id===id);if(!s||!node||!record)throw Error('未找到防水节点');modal(`更正节点：${node.name}`,waterproofNodeForm(node,record,true),d=>run('correctWaterproofNode',{...d,id:s.id,nodeId:node.id},'节点已更正，旧记录继续保留'),'保存更正');break;}
case 'submit-stage':{const s=p.stages.find(s=>s.id===id),blocks=s.kind==='final'?finalStageBlockers(p):[],waterproofNotice=s.kind==='waterproof'?'<div class="notice">5 个防水节点均已记录。提交时复用第 5 节点的现场照片，不需要再次拍摄。</div>':'',stageEvidence=s.kind==='waterproof'?'':captureField('stage','管家验收现场影像','必须由管家本次现场拍摄至少 3 张照片；视频可以补充，但不能代替这 3 张照片。照片自动写入拍摄时间水印。');modal(s.kind==='final'?'提交竣工验收与交付':'管家提交阶段验收',`${blocks.length?`<div class="notice orange">当前还不能提交：${blocks.map(esc).join('；')}。</div>`:''}${s.kind==='final'?'':`<div class="notice">师傅已申请验收。请管家现场核对全部清单。</div>`}${waterproofNotice}${checklistForm(s)}${textarea('note',s.kind==='final'?'竣工验收说明':'管家现场验收说明')}${stageEvidence}`,d=>{d.checks=s.checklist.filter(item=>d['check-'+item.id]).map(item=>item.id);return run('submitStage',{...d,id},s.kind==='final'?'竣工资料已提交主业主验收':'管家已提交主业主验收');},s.kind==='final'?'提交竣工验收':'提交主业主验收');break;}
case 'add-extra':modal('登记增项',extraForm(),d=>run('addExtra',d,'增项已登记，等待主业主确认'),'提交主业主确认');break;
case 'revise-extra':{const x=p.extras.find(x=>x.id===id);modal(`修改增项并建立 V${(x.version||1)+1}`,extraForm(x),d=>run('reviseExtra',{...d,id},'新版本已提交，旧版本继续保留'),'提交新版本确认');break;}
case 'accept-extra-proposal':{const x=p.extras.find(x=>x.id===id);modal('确认增项价格与工期',`<h3>${esc(x.name)} · V${x.version}</h3>${details([['增项总价',money(x.totalCost)],['预计延期',x.delayDays+' 天'],['施工内容',x.content]])}<div class="notice">确认后由管家安排责任师傅和施工日期。</div>`,()=>run('acceptExtraProposal',{id},'增项已确认，等待管家安排施工'),'确认增项');break;}
case 'reject-extra-proposal':noteFlow('拒绝本版增项','拒绝原因','rejectExtraProposal','本版增项已拒绝，管家可修改后重新提交');break;
case 'schedule-extra':{const x=p.extras.find(x=>x.id===id);modal('安排增项施工',`${select('worker','责任师傅',p.members.filter(m=>m.role==='worker').map(m=>[m.id,m.name+' · '+m.trade]),x.worker)}<div class="form-pair">${field('start','开始日期',x.start||TODAY,'date')}${field('end','结束日期',x.end||TODAY,'date')}</div><div class="notice">师傅只会看到已确认的施工内容、位置、日期和验收要求，不显示增项金额。</div>`,d=>run('scheduleExtra',{...d,id},'增项施工已安排'),'确认安排');break;}
case 'request-extra-acceptance':modal('施工完成，申请验收',`${textarea('note','施工完成说明')}${captureField('extra-application','师傅申请验收现场影像','必须现场拍摄至少 3 张照片；视频只能补充，不能替代照片。')}`,d=>run('requestExtraAcceptance',{...d,id},'已申请管家验收'),'申请管家验收');break;
case 'return-extra':noteFlow('退回继续施工','检查不通过原因和继续施工内容','returnExtraApplication','已退回责任师傅继续施工');break;
case 'submit-extra':modal('管家提交增项验收',`${textarea('note','管家现场验收说明')}${captureField('extra-submit','管家本次验收影像','必须重新现场拍摄至少 3 张照片；视频只能补充，不能替代照片。')}`,d=>run('submitExtraAcceptance',{...d,id},'增项已提交主业主验收'),'提交主业主验收');break;
case 'accept-extra-completion':{const x=p.extras.find(x=>x.id===id);modal('确认增项施工完成',`<h3>${esc(x.name)}</h3><p>确认施工内容和管家验收资料符合要求。</p>`,()=>run('acceptExtraCompletion',{id},'增项验收已完成'),'确认完成');break;}
case 'reject-extra-completion':noteFlow('增项验收不通过','需要继续处理的内容','rejectExtraCompletion','已交管家安排继续施工');break;
case 'followup-extra':noteFlow('安排增项继续施工','现场检查结果和继续施工要求','followupExtra','已安排责任师傅继续施工');break;
case 'cancel-extra-before':noteFlow('撤回并取消增项','取消原因','cancelExtraBeforeConfirmation','增项已取消，历史记录保留');break;
case 'request-extra-cancel':noteFlow('申请取消已确认增项','取消原因','requestExtraCancel','取消申请已提交主业主确认');break;
case 'accept-extra-cancel':modal('确认取消增项','<p>确认后本增项终止，已确认版本和处理记录继续保留。</p>',()=>run('acceptExtraCancel',{id},'增项已取消'),'确认取消');break;
case 'reject-extra-cancel':noteFlow('不同意取消增项','不同意原因','rejectExtraCancel','增项已恢复为待安排施工');break;
case 'request-extra-settlement':modal('申请终止并结算',`${field('completedQuantity','已完成工程量','','text','placeholder="如 厨房新增插座已完成 2 个"')}${field('actualCost','实际费用（元）','0','number','min="0" step="0.01"')}${textarea('note','现场情况与结算说明')}${captureField('extra-settlement','终止时现场情况','至少现场拍摄 1 张照片或 1 段视频，作为已完成工程量和现场情况依据。')}`,d=>run('requestExtraSettlement',{...d,id},'终止结算已提交主业主确认'),'提交终止结算');break;
case 'accept-extra-settlement':{const x=p.extras.find(x=>x.id===id);modal('确认终止结算',`${details([['已完成工程量',x.settlement?.completedQuantity],['实际费用',money(x.settlement?.actualCost)],['结算说明',x.settlement?.note]])}<p class="muted">确认后状态变为“已终止”，全部版本和现场记录保留。</p>`,()=>run('acceptExtraSettlement',{id},'增项已终止并完成结算'),'确认终止结算');break;}
case 'reject-extra-settlement':noteFlow('不同意终止结算','不同意原因','rejectExtraSettlement','已退回原施工状态');break;
case 'extra-price-access':{const m=p.members.find(m=>m.id===id),allowed=!m.extraPriceAuthorized;run('setExtraPriceAccess',{memberId:id,allowed},allowed?'已授权查看增项金额':'已取消增项金额权限');break;}
case 'add-material':modal('登记材料新批次',materialForm(),d=>run('addMaterial',d,'新批次已提交，等待主业主确认'),'登记并提交');break;
case 'edit-material':modal('更正本批资料',materialForm(p.materials.find(m=>m.id===id)),d=>run('editMaterial',{...d,id},'批次资料已更正并保留原资料记录'),'保存更正');break;
case 'supplement-material':modal('补拍材料现场影像',`${captureField('material-supplement','补拍现场影像','补齐后本批累计须达到至少 3 张现场照片和 1 段现场视频。照片自动写入拍摄时间水印。')}`,d=>run('supplementMaterialEvidence',{...d,id},'现场影像已补齐，主业主现在可以确认'),'保存现场影像');break;
case 'accept-material':{const m=p.materials.find(m=>m.id===id);modal('确认本批材料',`<p>${esc(m.name)} · ${esc(m.quantity)} ${esc(m.unit)}</p><p class="muted">确认本批材料信息及到货情况。其他批次需分别确认，施工质量仍需阶段验收。</p>`,()=>run('acceptMaterial',{id},'本批材料已确认'),'确认本批材料');break;}
case 'reject-material':noteFlow('反馈本批材料问题','材料有什么问题？','rejectMaterial','材料问题已交管家处理');break;
case 'resubmit-material':modal('提交材料处理结果',`${textarea('note','核查情况与处理结果')}${captureField('material-resubmit','最新现场影像','本次重新提交必须重新拍摄至少 3 张现场照片，并录制 1 段现场视频。')}`,d=>run('resubmitMaterial',{...d,id},'处理结果已提交，等待主业主重新确认'),'重新提交确认');break;
case 'schedule-form':scheduleForm(id);break;
case 'confirm-availability':{const a=p.availability.find(a=>a.id===id);scheduleForm(p.schedules.find(s=>s.trade===a.trade)?.id||'',id);break;}
case 'availability':modal('反馈可进场时间',`<div class="notice">先看其他工种进度，再反馈时间。管家协调后确认最终施工安排。</div>${field('date','最早可进场日期','2026-09-18','date')}${textarea('note','补充说明')}`,d=>run('availability',d,'进场时间已反馈，等待管家协调'),'提交给管家');break;
case 'invite':modal('邀请成员 · 本机演示',`<div class="notice">正式小程序将用邀请链接或二维码。这里模拟“对方申请加入”，不会向外发送邀请或消息。</div>${field('name','模拟申请人姓名')}${select('role','申请身份',[['worker','施工师傅'],['designer','设计师'],['family','家庭成员'],['owner','主业主']])}${select('trade','施工师傅的工种',['拆改工','泥瓦工','水电工','防水工','木工','油漆工','美缝工','安装工','保洁工'].map(t=>[t,t]))}<p class="muted tiny">工种只在“施工师傅”身份下生效。提交后出现在待核对列表，由管家审核。</p>`,d=>run('applyMember',d,'演示申请已收到，请核对身份后通过'),'模拟提交加入申请');break;
case 'approve-member':modal('确认成员身份',`<p>你已核对 ${esc(p.applications.find(a=>a.id===id)?.name)} 的姓名、身份和负责工种，确认加入本项目。</p>`,()=>run('approveMember',{id},'成员已加入项目'),'确认加入');break;
case 'reject-member':noteFlow('申请未通过','未通过原因','rejectMember','申请结果已记录');break;
case 'open-file':{const [did,index]=id.split('|'),f=p.designs.find(d=>d.id===did).files[Number(index)],local=localFiles.get(f.key);modal(f.kind==='dwg'?'CAD 源文件':'查看 PDF',`<p>${esc(f.name)}</p>${local?`<a class="primary full" href="${esc(local.url)}" ${f.kind==='dwg'?`download="${esc(f.name)}"`:'target="_blank" rel="noopener"'}>${f.kind==='dwg'?'保存 DWG 文件':'在浏览器打开 PDF'}</a>`:`<div class="notice">${f.sample?'这是原型示例资料卡，尚未提供真实文件。负责人或设计师可选择本机文件体验。':'名称已保留，刷新后需要重新选择本机文件预览。'}</div>`}<p class="muted" style="margin-top:15px">${f.kind==='dwg'?'DWG 需使用支持 CAD 的工具打开。':'浏览器根据自身能力显示或下载 PDF；微信端效果待正式开发验证。'}</p>`);break;}
case 'add-design':designForm();break;
case 'report-warranty':modal('新建售后／保修问题',`${field('title','问题标题')}${locationField('', '问题位置')}${textarea('description','具体情况')}${issueMediaField('warranty-report','照片或视频可选；可现场拍摄，也可从相册或文件补充。')}<div class="notice">此记录独立于原竣工验收，不会改变项目“已完工”状态。</div>`,d=>run('reportWarranty',d,'售后／保修问题已记录'),'保存售后问题');break;
case 'followup-warranty':noteFlow('记录售后处理进展','检查、联系或处理进展','followupWarranty','售后处理进展已记录');break;
case 'close-warranty':noteFlow('确认售后问题处理完成','确认说明','closeWarranty','售后／保修问题已完成');break;
}}
document.addEventListener('click',e=>{const t=e.target.closest('button,[data-go]');if(!t)return;try{if(t.dataset.locationOption!==undefined)toggleLocationOption(t);else if(t.dataset.role){actor.role=t.dataset.role;actor.worker='w1';route='home';detail='';filter='全部';render();}else if(t.dataset.project){projectId=t.dataset.project;navigate('home');}else if(t.dataset.go)navigate(t.dataset.go,t.dataset.id);else if(t.dataset.action)handle(t.dataset.action,t.dataset.id);else if(t.dataset.filter){filter=t.dataset.filter;render();}else if(t.dataset.designTab){designTab=t.dataset.designTab;render();}}catch(error){notify(error.message);}});
document.addEventListener('input',e=>{if(e.target.matches('.location-field input[type=text]'))syncLocationOptions(e.target);});
document.addEventListener('change',async e=>{if(e.target.id==='worker-picker'){actor.worker=e.target.value;render();}if(e.target.id==='show-history'){showHistory=e.target.checked;render();}if(e.target.type==='file'){const preview=$('#preview-'+e.target.name);if(preview){preview.textContent='正在处理预览与时间水印…';try{preview.innerHTML=media((await collectFiles(e.target)).filter(f=>['image','video'].includes(f.kind)));}catch(error){preview.textContent=error.message;}}}});
document.addEventListener('submit',e=>{if(e.target.id==='comment-form'){e.preventDefault();try{run('commentIssue',{id:detail,note:new FormData(e.target).get('note')},'留言已保存');}catch(error){notify(error.message);}}if(e.target.id==='warranty-comment-form'){e.preventDefault();try{run('commentWarranty',{id:detail,note:new FormData(e.target).get('note')},'售后留言已保存');}catch(error){notify(error.message);}}});
window.addEventListener('hashchange',()=>{const [r,id='']=location.hash.slice(1).split('/');if(pages[r]){route=r;detail=id;render();}});
const [initialRoute,initialId='']=location.hash.slice(1).split('/');if(pages[initialRoute]){route=initialRoute;detail=initialId;}render();
// Optional page tools share visible state and obey the active demo role's project access.
if(document.modelContext?.registerTool){const lifecycle=new AbortController(),register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
register({name:'read_renovation_demo',title:'查看装修原型状态',description:'读取当前演示身份可见的项目、问题、阶段、材料与增项状态。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('此工具不接受参数');return {role:actor.role,project:projectId,projects:visibleProjects(state,actor).map(p=>({id:p.id,name:p.name,issues:p.issues.map(i=>({id:i.id,title:i.title,status:i.status})),stages:p.stages.map(s=>({id:s.id,name:s.name,status:s.status})),materials:p.materials.map(m=>({id:m.id,name:m.name,status:m.status})),extras:(p.extras||[]).filter(x=>extraVisibleToActor(x,actor)).map(x=>({id:x.id,name:x.name,status:x.status,version:x.version}))}))};}});
register({name:'navigate_renovation_demo',title:'打开原型栏目',description:'打开当前项目页面；只改变页面，不完成验收或提交记录。',inputSchema:{type:'object',properties:{page:{type:'string',enum:['home','feed','schedule','issues','stages','materials','extras','warranty','design','people']}},required:['page'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='page')||!['home','feed','schedule','issues','stages','materials','extras','warranty','design','people'].includes(input.page))throw Error('页面参数无效');navigate(input.page);return {page:route,project:projectId};}});
window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
